{
  "findings": [
    {
      "check_id": "CKV_AZURE_41",
      "title": "Ensure that the expiration date is set on all secrets",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret 'database_connection_string' does not have an expiration date set, which can lead to the secret being valid indefinitely."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Secret value contains sensitive information",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "CRITICAL",
      "explanation": "The secret 'database_connection_string' contains sensitive information like 'sql_admin_password' which is a variable, but its value is not checked to be stored securely."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  depends_on   = [azurerm_mssql_database.legal_metadata_db]\n  expiration_date = timeadd(timestamp(), \"8760h\")\n}\n",
  "fix_summary": "Added an expiration date to the 'database_connection_string' secret. The expiration date is set to 1 year from the time of deployment."
}
